import React from 'react';
import { usePricingData } from '../hooks/usePricingData';

const PricingPage = () => {
  const pricingData = usePricingData();
  return (
    <div>
      <h1>Pricing Page</h1>
      <ul>
        {pricingData.map((item) => (
          <li key={item.id}>{item.name}: {item.price}</li>
        ))}
      </ul>
    </div>
  );
};

export default PricingPage;
